  for a in "" --android; do echo "== firefox-smoke $a"; timeout 300 node tests/tools/firefox-smoke.cjs "$ff" $a 2>&1 | tail -2; done
else echo "== firefox-smoke: пропущен (нет FIREFOX/GECKODRIVER)"; fi
